    assertEquals(6, FilenameUtils.getPrefixLength("~user\\a\\b\\c.txt"));
    assertEquals(9, FilenameUtils.getPrefixLength("//server/a/b/c.txt"));
    assertEquals(-1, FilenameUtils.getPrefixLength("\\\\\\a\\b\\c.txt"));
