@Test
public void testReadBuffer() throws IOException {
    final byte[] b = new byte[data.length * 2];
    int total = 0;
    for (int n = 0; n != -1; n = stream.read(b)) {
        assertFalse(closed, "closed");
        for (int i = 0; i < n; i++) {
            assertEquals(data[total + i], b[i], "read(b)");
